import fs from 'node:fs';
import path from 'node:path';
import assert from 'node:assert/strict';
import { fileURLToPath } from 'node:url';

// Overlay compatibility filename for 1.1.5-era source trees.
const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '../..');
const shell = fs.readFileSync(path.join(root, 'src/OrbitCord.App/WindowsShellIntegration.cs'), 'utf8');
assert.doesNotMatch(shell, /shell-v4-/,
  'v4 cache must not be generated by the simplified shell path');
assert.match(shell, /shell-v5-/,
  'custom shell icons must use v5 cache');
for (const size of [16, 24, 32, 48, 64, 128, 256]) {
  assert.match(shell, new RegExp(`\\b${size}\\b`), `multi-resolution shell icon must include ${size}px`);
}
assert.match(shell, /RenderTargetBitmap|DrawingVisual/,
  'icon frames must be rendered onto square transparent canvases');
assert.match(shell, /IconBitmapDecoder/,
  'ICO validation must use the managed WPF icon decoder');
assert.match(shell, /\.tmp/,
  'icon generation must remain atomic');
console.log('windows-shell-icon-v4-upgrade-compat: PASS');
